const metrics = $json;
const activeConnections = parseInt(metrics.active_connections, 10) || 0;
const waitingLocks = parseInt(metrics.waiting_locks, 10) || 0;
const dbSize = metrics.database_size || 'Bilinmiyor';
const leads24h = parseInt(metrics.new_leads_24h, 10) || 0;

// Eşik Değerleri (Thresholds)
const isConnCritical = activeConnections > 35;
const isLockCritical = waitingLocks > 3;
const alertRequired = isConnCritical || isLockCritical;

return [{
  json: {
    timestamp: new Date().toISOString(),
    activeConnections,
    waitingLocks,
    dbSize,
    leads24h,
    alertRequired,
    status: alertRequired ? 'WARNING' : 'HEALTHY',
    summary: `DB: ${dbSize} | Aktif Bağlantı: ${activeConnections} | Kilit: ${waitingLocks} | Son 24s Teklif: ${leads24h}`
  }
}];

